#include "stm32f10x.h"
#include "stm32f10x_tim.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

/* TIM3 挂在 APB1；系统 72MHz 时 TIM3 计数时钟也是 72MHz。
   CH1 的默认引脚是 PA6。 */
void TIM3_PWM_Init(void)
{
  GPIO_InitTypeDef         GPIO_InitStructure;
  TIM_TimeBaseInitTypeDef  TIM_TimeBaseStructure;
  TIM_OCInitTypeDef        TIM_OCInitStructure;

  /* ① 开时钟：TIM3 在 APB1，GPIOA 在 APB2。漏开时钟不会报错，只是完全没反应 */
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM3, ENABLE);
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);

  /* ② PA6 配成复用推挽，交给 TIM3_CH1 驱动 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_6;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  /* ③ 时基：72MHz / (71 + 1) = 1MHz 计数；1000 个计数一周期 → 1kHz */
  TIM_TimeBaseStructure.TIM_Prescaler         = 71;
  TIM_TimeBaseStructure.TIM_Period            = 999;
  TIM_TimeBaseStructure.TIM_CounterMode       = TIM_CounterMode_Up;
  TIM_TimeBaseStructure.TIM_ClockDivision     = TIM_CKD_DIV1;
  TIM_TimeBaseStructure.TIM_RepetitionCounter = 0;   /* 只有 TIM1/TIM8 用得到 */
  TIM_TimeBaseInit(TIM3, &TIM_TimeBaseStructure);

  /* ④ 通道 1 配成 PWM1，比较值 500 表示占空比 50% */
  TIM_OCStructInit(&TIM_OCInitStructure);
  TIM_OCInitStructure.TIM_OCMode      = TIM_OCMode_PWM1;
  TIM_OCInitStructure.TIM_OutputState = TIM_OutputState_Enable;
  TIM_OCInitStructure.TIM_Pulse       = 500;
  TIM_OCInitStructure.TIM_OCPolarity  = TIM_OCPolarity_High;
  TIM_OC1Init(TIM3, &TIM_OCInitStructure);

  /* ⑤ 打开 CCR 预装载：运行中改占空比时，新值等到下个更新事件才生效，不会出毛刺 */
  TIM_OC1PreloadConfig(TIM3, TIM_OCPreload_Enable);
  TIM_ARRPreloadConfig(TIM3, ENABLE);

  /* ⑥ 启动计数，PWM 立刻从 PA6 输出 */
  TIM_Cmd(TIM3, ENABLE);

  /* ⑦ 主动产生一次更新事件，把预分频与 ARR 的预装载值马上装入影子寄存器；
        不做这一步就要等一个完整周期后新配置才生效 */
  TIM_GenerateEvent(TIM3, TIM_EventSource_Update);
}

/* 运行中改占空比：TIM_SetCompare1(TIM3, 750);   → 75% */

/* 小结：至此 TIM3_CH1 在 PA6 上输出 1kHz、50% 占空比的 PWM；改占空比只需 TIM_SetCompare1。 */

#include "stm32f10x.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_flash.h"

/* 72MHz 是 STM32F103 的标准上限。返回 ERROR 说明 HSE 没起振，
   此时应停在 8MHz 的 HSI 上继续跑，不要强行切 PLL。 */
ErrorStatus RCC_Clock72MHz_Init(void)
{
  RCC_ClocksTypeDef clocks;

  /* ① 打开外部 8MHz 晶振并等它稳定（起振快慢和晶振、负载电容有关，必须等） */
  RCC_HSEConfig(RCC_HSE_ON);
  if (RCC_WaitForHSEStartUp() != SUCCESS)
  {
    return ERROR;
  }

  /* ② 先把分频定好：AHB = SYSCLK，APB2 = 72MHz，APB1 上限 36MHz 所以二分频 */
  RCC_HCLKConfig(RCC_SYSCLK_Div1);
  RCC_PCLK2Config(RCC_HCLK_Div1);
  RCC_PCLK1Config(RCC_HCLK_Div2);

  /* ③ 72MHz 需要 2 个 Flash 等待周期，并建议开预取缓冲，否则取指跟不上会跑飞 */
  FLASH_SetLatency(FLASH_Latency_2);
  FLASH_PrefetchBufferCmd(FLASH_PrefetchBuffer_Enable);

  /* ④ PLL：HSE 不分频直接进 PLL，乘 9 → 8MHz × 9 = 72MHz */
  RCC_PLLConfig(RCC_PLLSource_HSE_Div1, RCC_PLLMul_9);
  RCC_PLLCmd(ENABLE);
  while (RCC_GetFlagStatus(RCC_FLAG_PLLRDY) == RESET)
  {
    /* 等 PLL 锁定 */
  }

  /* ⑤ 切换系统时钟源到 PLL，并等到 SWS 真的变成 PLL（0x08） */
  RCC_SYSCLKConfig(RCC_SYSCLKSource_PLLCLK);
  while (RCC_GetSYSCLKSource() != 0x08)
  {
  }

  /* ⑥ 回读校验，配置成功时 SYSCLK/HCLK 都是 72MHz，PCLK1 是 36MHz */
  RCC_GetClocksFreq(&clocks);
  if (clocks.SYSCLK_Frequency != 72000000)
  {
    return ERROR;
  }
  return SUCCESS;
}

/* 小结：至此系统时钟为 HSE 8MHz × 9 = 72MHz，APB1 36MHz、APB2 72MHz，并已回读校验。 */

#include "stm32f10x.h"
#include "stm32f10x_adc.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

/* 采样 PA0（ADC1_IN0）。返回值 0~4095，对应 0~3.3V。 */
uint16_t ADC1_ReadChannel0(void)
{
  GPIO_InitTypeDef GPIO_InitStructure;
  ADC_InitTypeDef  ADC_InitStructure;
  uint16_t value;

  /* ① 开 GPIOA 与 ADC1 时钟（都在 APB2），并把 ADC 时钟分到 12MHz */
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_ADC1, ENABLE);
  RCC_ADCCLKConfig(RCC_PCLK2_Div6);   /* 72MHz / 6 = 12MHz，上限 14MHz */

  /* ② 模拟输入引脚必须配成 GPIO_Mode_AIN，不能配成浮空或上拉 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_0;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AIN;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  /* ③ 独立模式、单次、非扫描：一次只转一个通道，软件启动 */
  ADC_InitStructure.ADC_Mode               = ADC_Mode_Independent;
  ADC_InitStructure.ADC_ScanConvMode       = DISABLE;
  ADC_InitStructure.ADC_ContinuousConvMode = DISABLE;
  ADC_InitStructure.ADC_ExternalTrigConv   = ADC_ExternalTrigConv_None;
  ADC_InitStructure.ADC_DataAlign          = ADC_DataAlign_Right;
  ADC_InitStructure.ADC_NbrOfChannel       = 1;
  ADC_Init(ADC1, &ADC_InitStructure);

  /* ④ 规则组第 1 个转换 = 通道 0，采样时间 55.5 个周期（信号源阻抗大就再加长） */
  ADC_RegularChannelConfig(ADC1, ADC_Channel_0, 1, ADC_SampleTime_55Cycles5);
  ADC_Cmd(ADC1, ENABLE);

  /* ⑤ 上电必须先复位校准再启动校准，不做的话前若干次结果明显偏 */
  ADC_ResetCalibration(ADC1);
  while (ADC_GetResetCalibrationStatus(ADC1) == SET)
  {
  }
  ADC_StartCalibration(ADC1);
  while (ADC_GetCalibrationStatus(ADC1) == SET)
  {
  }

  /* ⑥ 软件启动一次转换，等 EOC 后读结果；读 DR 会自动清 EOC */
  ADC_SoftwareStartConvCmd(ADC1, ENABLE);
  while (ADC_GetFlagStatus(ADC1, ADC_FLAG_EOC) == RESET)
  {
  }
  value = ADC_GetConversionValue(ADC1);

  return value;
}

/* 小结：至此 ADC1 已完成一次 PA0 采样：开时钟 → 配模拟引脚 → 初始化 → 自校准 → 启动 → 读值。 */

#include "stm32f10x.h"
#include "stm32f10x_i2c.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

/* 标准两段式读寄存器：先写寄存器地址（假写），再重复起始读一个字节。
   devAddr 是不含读写位的 7 位地址，例如 AT24C02 是 0x50。 */
void I2C1_Init(void)
{
  GPIO_InitTypeDef GPIO_InitStructure;
  I2C_InitTypeDef  I2C_InitStructure;

  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE);

  /* SCL/SDA 必须是复用开漏，外部要接上拉电阻（模块板通常已自带） */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_6 | GPIO_Pin_7;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_OD;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOB, &GPIO_InitStructure);

  I2C_InitStructure.I2C_Mode                = I2C_Mode_I2C;
  I2C_InitStructure.I2C_DutyCycle           = I2C_DutyCycle_2;
  I2C_InitStructure.I2C_OwnAddress1         = 0x0A;    /* 做主机时随意，不冲突即可 */
  I2C_InitStructure.I2C_Ack                 = I2C_Ack_Enable;
  I2C_InitStructure.I2C_AcknowledgedAddress = I2C_AcknowledgedAddress_7bit;
  I2C_InitStructure.I2C_ClockSpeed          = 100000; /* 100kHz，快速模式可到 400kHz */
  I2C_Init(I2C1, &I2C_InitStructure);

  I2C_Cmd(I2C1, ENABLE);
}

uint8_t I2C1_ReadRegister(uint8_t devAddr, uint8_t reg)
{
  uint8_t data;

  /* ① 总线忙时不发起始，否则会打断别人正在进行的传输 */
  while (I2C_GetFlagStatus(I2C1, I2C_FLAG_BUSY) == SET)
  {
  }

  /* ② 起始 + 等 SB（EV5） */
  I2C_GenerateSTART(I2C1, ENABLE);
  while (I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT) != SUCCESS)
  {
  }

  /* ③ 发从机地址 + 写方向，等 EV6 */
  I2C_Send7bitAddress(I2C1, devAddr, I2C_Direction_Transmitter);
  while (I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED) != SUCCESS)
  {
  }

  /* ④ 发寄存器地址，等 EV8_2（字节真正发完） */
  I2C_SendData(I2C1, reg);
  while (I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED) != SUCCESS)
  {
  }

  /* ⑤ 重复起始，再发地址 + 读方向，等 EV6 */
  I2C_GenerateSTART(I2C1, ENABLE);
  while (I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT) != SUCCESS)
  {
  }
  I2C_Send7bitAddress(I2C1, devAddr, I2C_Direction_Receiver);
  while (I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED) != SUCCESS)
  {
  }

  /* ⑥ 只读一个字节：先关应答再发停止，然后等 RXNE 取数据 */
  I2C_AcknowledgeConfig(I2C1, DISABLE);
  I2C_GenerateSTOP(I2C1, ENABLE);
  while (I2C_GetFlagStatus(I2C1, I2C_FLAG_RXNE) == RESET)
  {
  }
  data = I2C_ReceiveData(I2C1);

  /* ⑦ 恢复应答，方便下一次传输 */
  I2C_AcknowledgeConfig(I2C1, ENABLE);

  return data;
}

/* 小结：至此完成一次 I2C 寄存器读：起始 → 写地址 → 写寄存器号 → 重复起始 → 读地址 → 关应答 → 停止。 */

#include "stm32f10x.h"
#include "stm32f10x_sdio.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

/* SD 卡初始化阶段必须把 SDIO_CK 降到 400kHz 以下，卡识别成功后才能提速。
   SDIO_CK = HCLK / (2 × ClockDiv)，HCLK = 72MHz 时要 400kHz 就取 ClockDiv = 90。 */
void SDIO_LowLevel_Init(void)
{
  GPIO_InitTypeDef GPIO_InitStructure;
  SDIO_InitTypeDef SDIO_InitStructure;

  /* ① 开 SDIO（AHB）与 PC/PD 端口时钟 */
  RCC_AHBPeriphClockCmd(RCC_AHBPeriph_SDIO, ENABLE);
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOC | RCC_APB2Periph_GPIOD, ENABLE);

  /* ② D0~D3 与 CK 在 PC8~PC12，CMD 在 PD2，全部复用推挽 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_8 | GPIO_Pin_9 | GPIO_Pin_10 |
                                  GPIO_Pin_11 | GPIO_Pin_12;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOC, &GPIO_InitStructure);

  GPIO_InitStructure.GPIO_Pin = GPIO_Pin_2;
  GPIO_Init(GPIOD, &GPIO_InitStructure);

  /* ③ 给卡上电，先不开时钟 */
  SDIO_SetPowerState(SDIO_PowerState_ON);

  /* ④ 只开 1 位总线，时钟沿上升沿，无硬件流控，400kHz */
  SDIO_InitStructure.SDIO_ClockEdge          = SDIO_ClockEdge_Rising;
  SDIO_InitStructure.SDIO_ClockBypass        = SDIO_ClockBypass_Disable;
  SDIO_InitStructure.SDIO_ClockPowerSave     = SDIO_ClockPowerSave_Disable;
  SDIO_InitStructure.SDIO_BusWide            = SDIO_BusWide_1b;
  SDIO_InitStructure.SDIO_HardwareFlowControl = SDIO_HardwareFlowControl_Disable;
  SDIO_InitStructure.SDIO_ClockDiv           = 90;
  SDIO_Init(&SDIO_InitStructure);

  /* ⑤ 最后才使能时钟输出 */
  SDIO_ClockCmd(ENABLE);
}

/* 发一条无参数、无响应的命令（CMD0 = GO_IDLE_STATE），并等命令发送完成 */
uint8_t SDIO_SendCmd0(void)
{
  SDIO_CmdInitTypeDef SDIO_CmdInitStructure;
  uint32_t timeout = 0x000FFFFF;

  SDIO_CmdInitStructure.SDIO_Argument = 0x00000000;
  SDIO_CmdInitStructure.SDIO_CmdIndex = 0;
  SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_No;
  SDIO_CmdInitStructure.SDIO_Wait     = SDIO_Wait_No;
  SDIO_CmdInitStructure.SDIO_CPSM     = SDIO_CPSM_Enable;
  SDIO_SendCommand(&SDIO_CmdInitStructure);

  while ((SDIO_GetFlagStatus(SDIO_FLAG_CMDSENT) == RESET) && (timeout > 0))
  {
    timeout--;
  }
  SDIO_ClearFlag(SDIO_FLAG_CMDSENT);

  return (timeout > 0) ? 1 : 0;
}

/* 提速：卡识别完成后切到 4 位总线、24MHz */
void SDIO_HighSpeed_Init(void)
{
  SDIO_InitTypeDef SDIO_InitStructure;

  SDIO_InitStructure.SDIO_ClockEdge          = SDIO_ClockEdge_Rising;
  SDIO_InitStructure.SDIO_ClockBypass        = SDIO_ClockBypass_Disable;
  SDIO_InitStructure.SDIO_ClockPowerSave     = SDIO_ClockPowerSave_Disable;
  SDIO_InitStructure.SDIO_BusWide            = SDIO_BusWide_4b;
  SDIO_InitStructure.SDIO_HardwareFlowControl = SDIO_HardwareFlowControl_Disable;
  SDIO_InitStructure.SDIO_ClockDiv           = 1;   /* 72 / (2 × 1) = 36MHz，实际按卡支持能力取 */
  SDIO_Init(&SDIO_InitStructure);
}

/* 小结：至此 SDIO 已上电、以 400kHz 发出 CMD0，并给出识别成功后切 4 位总线的配置。 */

#include "stm32f10x.h"
#include "stm32f10x_usart.h"
#include "misc.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

static volatile uint8_t g_rxByte = 0;
static volatile uint8_t g_rxReady = 0;

/* 波特率由 PCLK2 分频得到，所以改主频后必须重算，否则收到的全是乱码。 */
void USART1_Init(void)
{
  GPIO_InitTypeDef  GPIO_InitStructure;
  USART_InitTypeDef USART_InitStructure;
  NVIC_InitTypeDef  NVIC_InitStructure;

  /* ① 开 GPIOA 与 USART1 时钟（都在 APB2） */
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_USART1, ENABLE);

  /* ② TX 复用推挽，RX 上拉输入 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_9;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  GPIO_InitStructure.GPIO_Pin  = GPIO_Pin_10;
  GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  /* ③ 115200、8 位数据、1 位停止、无校验、无硬件流控 */
  USART_InitStructure.USART_BaudRate            = 115200;
  USART_InitStructure.USART_WordLength          = USART_WordLength_8b;
  USART_InitStructure.USART_StopBits            = USART_StopBits_1;
  USART_InitStructure.USART_Parity              = USART_Parity_No;
  USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
  USART_InitStructure.USART_Mode                = USART_Mode_Tx | USART_Mode_Rx;
  USART_Init(USART1, &USART_InitStructure);

  /* ④ 打开接收中断并配 NVIC */
  USART_ITConfig(USART1, USART_IT_RXNE, ENABLE);
  NVIC_InitStructure.NVIC_IRQChannel                   = USART1_IRQn;
  NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
  NVIC_InitStructure.NVIC_IRQChannelSubPriority        = 0;
  NVIC_InitStructure.NVIC_IRQChannelCmd                = ENABLE;
  NVIC_Init(&NVIC_InitStructure);

  USART_Cmd(USART1, ENABLE);
}

/* 发送一个字节：必须等 TXE（发送数据寄存器空），否则会覆盖上一字节直接丢数据 */
void USART1_SendByte(uint8_t data)
{
  while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET)
  {
  }
  USART_SendData(USART1, data);
}

void USART1_SendString(const char *str)
{
  while (*str != '\0')
  {
    USART1_SendByte((uint8_t)*str);
    str++;
  }
  /* 等最后一个字节真正移出（TC），此时才能安全断电或切低功耗 */
  while (USART_GetFlagStatus(USART1, USART_FLAG_TC) == RESET)
  {
  }
}

/* 接收中断：读 DR 会自动清 RXNE；不读就会一直重入 */
void USART1_IRQHandler(void)
{
  if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET)
  {
    g_rxByte = (uint8_t)USART_ReceiveData(USART1);
    g_rxReady = 1;
  }
}

/* 小结：至此 USART1 能发送字符串并以中断方式接收字节，串口助手 115200 即可看到收发。 */

#include "stm32f10x.h"
#include "stm32f10x_can.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

/* APB1 = 36MHz 时：预分频 4 → 单个 tq = 9MHz；1 + BS1(15) + BS2(2) = 18 tq
   → 9MHz / 18 = 500kbps，采样点在 88.9%。改动任一参数都要重算。 */
void CAN1_Init(void)
{
  GPIO_InitTypeDef      GPIO_InitStructure;
  CAN_InitTypeDef       CAN_InitStructure;
  CAN_FilterInitTypeDef CAN_FilterInitStructure;

  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_CAN1, ENABLE);

  /* CAN_RX 是输入，CAN_TX 是复用推挽 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_11;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_IPU;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  GPIO_InitStructure.GPIO_Pin  = GPIO_Pin_12;
  GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  CAN_StructInit(&CAN_InitStructure);
  CAN_InitStructure.CAN_Prescaler = 4;
  CAN_InitStructure.CAN_Mode      = CAN_Mode_Normal;
  CAN_InitStructure.CAN_SJW       = CAN_SJW_1tq;
  CAN_InitStructure.CAN_BS1       = CAN_BS1_15tq;
  CAN_InitStructure.CAN_BS2       = CAN_BS2_2tq;
  CAN_InitStructure.CAN_TTCM      = DISABLE;
  CAN_InitStructure.CAN_ABOM      = ENABLE;   /* 自动离线恢复 */
  CAN_InitStructure.CAN_AWUM      = DISABLE;
  CAN_InitStructure.CAN_NART      = DISABLE;
  CAN_InitStructure.CAN_RFLM      = DISABLE;
  CAN_InitStructure.CAN_TXFP      = DISABLE;
  if (CAN_Init(CAN1, &CAN_InitStructure) != CAN_InitStatus_Success)
  {
    return;   /* 初始化握手超时，通常是时钟没开 */
  }

  /* 过滤器：32 位、掩码全 0 表示「全部收下」，挂到 FIFO0。
     不配这一步一个报文都收不到，是 CAN 调不通最常见的原因。 */
  CAN_FilterInitStructure.CAN_FilterNumber         = 0;
  CAN_FilterInitStructure.CAN_FilterMode           = CAN_FilterMode_IdMask;
  CAN_FilterInitStructure.CAN_FilterScale          = CAN_FilterScale_32bit;
  CAN_FilterInitStructure.CAN_FilterIdHigh         = 0x0000;
  CAN_FilterInitStructure.CAN_FilterIdLow          = 0x0000;
  CAN_FilterInitStructure.CAN_FilterMaskIdHigh     = 0x0000;
  CAN_FilterInitStructure.CAN_FilterMaskIdLow      = 0x0000;
  CAN_FilterInitStructure.CAN_FilterFIFOAssignment = CAN_Filter_FIFO0;
  CAN_FilterInitStructure.CAN_FilterActivation     = ENABLE;
  CAN_FilterInit(&CAN_FilterInitStructure);
}

/* 发一帧标准数据帧，ID = 0x123，8 字节；返回 1 表示发成功。 */
uint8_t CAN1_SendFrame(const uint8_t *payload)
{
  CanTxMsg TxMessage;
  uint8_t  mailbox;
  uint8_t  i;
  uint32_t timeout = 0x000FFFFF;

  TxMessage.StdId = 0x123;
  TxMessage.ExtId = 0x00;
  TxMessage.IDE   = CAN_ID_STD;
  TxMessage.RTR   = CAN_RTR_DATA;
  TxMessage.DLC   = 8;
  for (i = 0; i < 8; i++)
  {
    TxMessage.Data[i] = payload[i];
  }

  /* ① 找一个空邮箱发出；三个邮箱都满时返回 CAN_NO_MB */
  mailbox = CAN_Transmit(CAN1, &TxMessage);
  if (mailbox == CAN_NO_MB)
  {
    return 0;
  }

  /* ② 轮询该邮箱的发送结果，注意要带超时，否则总线异常时会死等 */
  while ((CAN_TransmitStatus(CAN1, mailbox) == CAN_TxStatus_Pending) && (timeout > 0))
  {
    timeout--;
  }

  return (CAN_TransmitStatus(CAN1, mailbox) == CAN_TxStatus_Ok) ? 1 : 0;
}

