#include "stm32f10x.h"
#include "stm32f10x_fsmc.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_gpio.h"

/* FSMC 把外部器件映射进地址空间，配置完后按地址读写即可，不必再调函数。
   本例：Bank1 / NORSRAM1（NE1），16 位数据总线，A16 作 RS 线。
   - 命令：0x60000000（A16 = 0）
   - 数据：0x60020000（A16 = 1；16 位存储器的 A16 对应 HADDR 第 17 位）
   注意：FSMC 只在高密度/互联型上有，F103C8 这类中容量芯片没有。 */
#define LCD_BASE        0x60000000UL
#define LCD_REG_ADDR    (LCD_BASE)
#define LCD_DATA_ADDR   (LCD_BASE + 0x00020000UL)

#define LCD_REG   (*(volatile uint16_t *)LCD_REG_ADDR)
#define LCD_DATA  (*(volatile uint16_t *)LCD_DATA_ADDR)

void FSMC_LCD_Init(void)
{
  GPIO_InitTypeDef GPIO_InitStructure;
  FSMC_NORSRAMInitTypeDef  FSMC_NORSRAMInitStructure;
  FSMC_NORSRAMTimingInitTypeDef FSMC_TimingStructure;
  volatile uint16_t d;

  /* ① 开 FSMC（AHB）与 PD/PE 端口时钟 */
  RCC_AHBPeriphClockCmd(RCC_AHBPeriph_FSMC, ENABLE);
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOD | RCC_APB2Periph_GPIOE, ENABLE);

  /* ② PD：D0/D1/D2/D3/D13/D14/D15、NOE、NWE、NE1、A16 全部复用推挽 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_0 | GPIO_Pin_1 | GPIO_Pin_4 | GPIO_Pin_5 |
                                  GPIO_Pin_7 | GPIO_Pin_8 | GPIO_Pin_9 | GPIO_Pin_10 |
                                  GPIO_Pin_11 | GPIO_Pin_14 | GPIO_Pin_15;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOD, &GPIO_InitStructure);

  /* ③ PE：D4~D12（PE7~PE15）也是复用推挽 */
  GPIO_InitStructure.GPIO_Pin = GPIO_Pin_7 | GPIO_Pin_8 | GPIO_Pin_9 | GPIO_Pin_10 |
                                GPIO_Pin_11 | GPIO_Pin_12 | GPIO_Pin_13 |
                                GPIO_Pin_14 | GPIO_Pin_15;
  GPIO_Init(GPIOE, &GPIO_InitStructure);

  /* ④ 时序：ADDSET/DATAST 单位为 HCLK 周期，取值过小会读到 0xFF 或随机值 */
  FSMC_TimingStructure.FSMC_AddressSetupTime      = 3;
  FSMC_TimingStructure.FSMC_AddressHoldTime       = 0;
  FSMC_TimingStructure.FSMC_DataSetupTime         = 8;
  FSMC_TimingStructure.FSMC_BusTurnAroundDuration = 0;
  FSMC_TimingStructure.FSMC_CLKDivision           = 0;
  FSMC_TimingStructure.FSMC_DataLatency           = 0;
  FSMC_TimingStructure.FSMC_AccessMode            = FSMC_AccessMode_A;

  /* ⑤ 存储体配置：异步、非复用、16 位、SRAM 类型、写使能 */
  FSMC_NORSRAMInitStructure.FSMC_Bank                  = FSMC_Bank1_NORSRAM1;
  FSMC_NORSRAMInitStructure.FSMC_DataAddressMux        = FSMC_DataAddressMux_Disable;
  FSMC_NORSRAMInitStructure.FSMC_MemoryType            = FSMC_MemoryType_SRAM;
  FSMC_NORSRAMInitStructure.FSMC_MemoryDataWidth       = FSMC_MemoryDataWidth_16b;
  FSMC_NORSRAMInitStructure.FSMC_BurstAccessMode       = FSMC_BurstAccessMode_Disable;
  FSMC_NORSRAMInitStructure.FSMC_AsynchronousWait      = FSMC_AsynchronousWait_Disable;
  FSMC_NORSRAMInitStructure.FSMC_WaitSignalPolarity    = FSMC_WaitSignalPolarity_Low;
  FSMC_NORSRAMInitStructure.FSMC_WrapMode              = FSMC_WrapMode_Disable;
  FSMC_NORSRAMInitStructure.FSMC_WaitSignalActive      = FSMC_WaitSignalActive_BeforeWaitState;
  FSMC_NORSRAMInitStructure.FSMC_WriteOperation        = FSMC_WriteOperation_Enable;
  FSMC_NORSRAMInitStructure.FSMC_WaitSignal            = FSMC_WaitSignal_Disable;
  FSMC_NORSRAMInitStructure.FSMC_ExtendedMode          = FSMC_ExtendedMode_Disable;
  FSMC_NORSRAMInitStructure.FSMC_WriteBurst            = FSMC_WriteBurst_Disable;
  FSMC_NORSRAMInitStructure.FSMC_ReadWriteTimingStruct = &FSMC_TimingStructure;
  FSMC_NORSRAMInitStructure.FSMC_WriteTimingStruct     = &FSMC_TimingStructure;
  FSMC_NORSRAMInit(&FSMC_NORSRAMInitStructure);

  /* ⑥ 使能 Bank1，之后就能按地址读写了 */
  FSMC_NORSRAMCmd(FSMC_Bank1_NORSRAM1, ENABLE);

  /* ⑦ 等一小会儿再访问，确保存储体已经完成使能时序（LCD 上电复位通常需要更久） */
  for (d = 0; d < 1000; d++)
  {
    /* 空转即可，这里不是精确延时 */
  }
}

/* 写命令与数据：一次地址访问就是一次总线时序 */
void LCD_WriteCmd(uint16_t cmd)
{
  LCD_REG = cmd;
}

void LCD_WriteData(uint16_t data)
{
  LCD_DATA = data;
}

