  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_13;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_Out_PP;   /* 推挽输出 */
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_2MHz;    /* 点灯用低速即可，EMI 更小 */
  GPIO_Init(GPIOC, &GPIO_InitStructure);

  /* ③ 初始灭灯（PC13 低电平亮，所以先拉高） */
  GPIO_SetBits(GPIOC, GPIO_Pin_13);
}

/* 极简忙等延时，仅用于演示；实际项目请用 SysTick 或定时器 */
static void Delay(volatile uint32_t count)
{
  while (count--)
  {
  }
}

void LED_Blink(void)
{
  while (1)
  {
    GPIO_ResetBits(GPIOC, GPIO_Pin_13);   /* 拉低 → 亮 */
    Delay(2000000);
    GPIO_SetBits(GPIOC, GPIO_Pin_13);     /* 拉高 → 灭 */
    Delay(2000000);
  }
}

