/* CEC 是 HDMI 的单线控制总线，速率固定 100Hz 级的位时序。
   本模块只在 STM32F100 Value line 等少数型号上存在，
   引脚通过 GPIO_PinRemapConfig(GPIO_Remap_CEC, ENABLE) 重映射出来。 */
void CEC_Init_Demo(void)
{
  GPIO_InitTypeDef GPIO_InitStructure;
  CEC_InitTypeDef  CEC_InitStructure;

  RCC_APB1PeriphClockCmd(RCC_APB1Periph_CEC, ENABLE);
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB | RCC_APB2Periph_AFIO, ENABLE);

  /* ① CEC 引脚是复用开漏，外部必须接上拉（一般是 27k 到 3.3V） */
  GPIO_PinRemapConfig(GPIO_Remap_CEC, ENABLE);
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_8;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_OD;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOB, &GPIO_InitStructure);

  /* ② 误差容忍模式都选标准模式，先按保守配置跑通再加宽 */
  CEC_InitStructure.CEC_BitTimingMode = CEC_BitTimingStdMode;
  CEC_InitStructure.CEC_BitPeriodMode = CEC_BitPeriodStdMode;
  CEC_Init(&CEC_InitStructure);

  /* ③ 预分频：把 CEC 时钟分到 32.768kHz。按 CEC 输入 8MHz 算约 244，
        实际请按所用型号的 CEC 时钟源重新计算 */
  CEC_SetPrescaler(244);

  /* ④ 设自己的逻辑地址（0~14，0x0F 表示未分配） */
  CEC_OwnAddressConfig(0x04);

  /* ⑤ 使能 CEC */
  CEC_Cmd(ENABLE);
}

/* 发一条最短的 CEC 帧：One Touch Play，广播（0x0F）→ TV（0x00） */
void CEC_SendOneTouchPlay(void)
{
  CEC_StartOfMessage();

  /* 第 1 字节：发起方 0x04，目标 0x00 → 0x40 */
  CEC_SendDataByte(0x40);
  /* 第 2 字节：操作码 0x04 = Image View On */
  CEC_SendDataByte(0x04);

  /* 结束帧并产生 EOM，硬件自动加上字节的 EOM/ACK 位 */
  CEC_EndOfMessageCmd(ENABLE);

  /* 等发送完成 */
  while (CEC_GetFlagStatus(CEC_FLAG_TEOM) == RESET)
  {
  }
  CEC_ClearFlag(CEC_FLAG_TEOM);
}

