#include "stm32f10x.h"
#include "stm32f10x_rcc.h"
#include "stm32f10x_pwr.h"
#include "stm32f10x_rtc.h"

/* RTC 在备份域里，靠纽扣电池供电，主电断开也继续走时。
   流程的关键是「先解锁备份域 → 等 LSE 起振 → 再使能 RTC 时钟」。 */
uint8_t RTC_Init(void)
{
  uint32_t timeout = 0x000FFFFF;

  /* ① PWR 与 BKP 时钟都要开，再解除备份域写保护 */
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
  PWR_BackupAccessCmd(ENABLE);

  /* ② 打开 32.768kHz 外部低速晶振，并等 LSERDY。LSE 起振慢，超时判据不能省 */
  RCC_LSEConfig(RCC_LSE_ON);
  while ((RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET) && (timeout > 0))
  {
    timeout--;
  }
  if (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET)
  {
    return 0;   /* 晶振没起振，多半是没焊或负载电容不对 */
  }

  /* ③ 选 LSE 作 RTC 时钟源并使能 */
  RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);
  RCC_RTCCLKCmd(ENABLE);

  /* ④ 等寄存器同步，之后每次写 RTC 都要等上一次写完成 */
  RTC_WaitForSynchro();
  RTC_WaitForLastTask();

  /* ⑤ 32.768kHz / 32768 = 1Hz，所以分频值写 32767 */
  RTC_SetPrescaler(32767);
  RTC_WaitForLastTask();

  /* ⑥ 从 0 开始计秒 */
  RTC_SetCounter(0);
  RTC_WaitForLastTask();

  return 1;
}

/* 读当前秒数；RTC_GetCounter 内部已处理高低字读出时的翻转问题 */
uint32_t RTC_GetSeconds(void)
{
  return RTC_GetCounter();
}

/* 小结：至此 RTC 以 LSE 为源、1Hz 计秒，可直接用 RTC_GetCounter 读出上电以来的秒数。 */

#include "stm32f10x.h"
#include "stm32f10x_pwr.h"
#include "stm32f10x_bkp.h"
#include "stm32f10x_rcc.h"

/* 备份寄存器是 16 位、掉电不丢的小存储，常用来存「已初始化」标志、
   校准值、设备序列号等。写入前必须先解除备份域写保护。 */
void BKP_Demo(void)
{
  uint16_t magic;

  /* ① PWR 与 BKP 时钟，然后解锁备份域 */
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
  PWR_BackupAccessCmd(ENABLE);

  /* ② 读出来看是不是第一次上电（备份域复位后是全 0） */
  magic = BKP_ReadBackupRegister(BKP_DR1);

  if (magic != 0xA5A5)
  {
    /* ③ 第一次运行：写入标志，顺便存一个配置值 */
    BKP_WriteBackupRegister(BKP_DR1, 0xA5A5);
    BKP_WriteBackupRegister(BKP_DR2, 0x1234);
  }

  /* ④ 防篡改引脚（PC13 的 TAMPER 功能）：设电平并开中断 */
  BKP_TamperPinLevelConfig(BKP_TamperPinLevel_High);
  BKP_TamperPinCmd(ENABLE);
  BKP_ITConfig(ENABLE);
}

/* 进 TAMPER 中断后要清标志，否则会一直重入 */
void TAMPER_IRQHandler(void)
{
  if (BKP_GetITStatus() != RESET)
  {
    BKP_ClearITPendingBit();
  }
}

