/* PVD 在电源电压跌破设定阈值时产生中断，用来提前保存数据或告警。 */
void PWR_PVD_Init(void)
{
  EXTI_InitTypeDef EXTI_InitStructure;
  NVIC_InitTypeDef NVIC_InitStructure;

  RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);

  /* ① 阈值选 2.6V，并打开 PVD */
  PWR_PVDLevelConfig(PWR_PVDLevel_2V6);
  PWR_PVDCmd(ENABLE);

  /* ② PVD 事件固定走 EXTI 线 16，只能配成中断，没有对应引脚 */
  EXTI_InitStructure.EXTI_Line    = EXTI_Line16;
  EXTI_InitStructure.EXTI_Mode    = EXTI_Mode_Interrupt;
  EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Rising_Falling;
  EXTI_InitStructure.EXTI_LineCmd = ENABLE;
  EXTI_Init(&EXTI_InitStructure);

  NVIC_InitStructure.NVIC_IRQChannel                   = PVD_IRQn;
  NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
  NVIC_InitStructure.NVIC_IRQChannelSubPriority        = 0;
  NVIC_InitStructure.NVIC_IRQChannelCmd                = ENABLE;
  NVIC_Init(&NVIC_InitStructure);
}

void PVD_IRQHandler(void)
{
  if (EXTI_GetITStatus(EXTI_Line16) != RESET)
  {
    /* 这里做掉电前的紧急处理：保存参数到 BKP、关外设等 */
    EXTI_ClearITPendingBit(EXTI_Line16);
  }
}

/* 进入 STOP：所有时钟停住，功耗降到十几 uA。
   唤醒源可以是 EXTI 的任意外部中断；唤醒后系统时钟自动切回 HSI，必须重新配置时钟树。 */
void PWR_EnterStop_Demo(void)
{
  /* ① 使能 WKUP 引脚（PA0）作为唤醒源，唤醒后产生上升沿 */
  PWR_WakeUpPinCmd(ENABLE);

  /* ② 清掉唤醒标志，避免刚进就立刻被旧标志唤醒 */
  PWR_ClearFlag(PWR_FLAG_WU);

  /* ③ 低压稳压器保持开启，用 WFI 进入 STOP */
  PWR_EnterSTOPMode(PWR_Regulator_ON, PWR_STOPEntry_WFI);

  /* ④ 被唤醒后在这里恢复时钟（示例用 HSI 8MHz 先跑起来） */
  RCC_SYSCLKConfig(RCC_SYSCLKSource_HSI);
}

/* 小结：至此 PVD 会在电压跌破 2.6V 时进中断，STOP 模式可由 WKUP（PA0）唤醒并恢复时钟。 */

#include "stm32f10x.h"
#include "stm32f10x_wwdg.h"
#include "stm32f10x_rcc.h"

/* WWDG 由 PCLK1 驱动，计数时钟 = PCLK1 / 4096 / 预分频。
   PCLK1 = 36MHz、预分频 8 → 约 1.1kHz，一个计数约 910us；
   计数从 0x7F 递减到 0x3F 触发复位，可容忍约 63 × 910us ≈ 57ms。
   窗口值 0x5F 意味着计数还高于 0x5F 时喂狗会立刻复位。 */
void WWDG_Init(void)
{
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_WWDG, ENABLE);

  /* ① 预分频：WWDG_Prescaler_1/2/4/8 */
  WWDG_SetPrescaler(WWDG_Prescaler_8);

  /* ② 窗口值必须大于 0x40，且小于初值 */
  WWDG_SetWindowValue(0x5F);

  /* ③ 使能并装载初值（初值必须 >= 0x40 且 <= 0x7F） */
  WWDG_Enable(0x7F);

  /* ④ 可选：打开提前唤醒中断（EWI），在计数降到 0x40 前再喂一次 */
  WWDG_EnableIT();
}

/* 喂狗必须发生在计数降到窗口值以下、又还没到 0x40 的那个区间里。
   喂得太早（计数仍高于窗口值）同样触发复位，这是设计意图，不是 bug。 */
void WWDG_Feed(void)
{
  WWDG_SetCounter(0x7F);
}

/* 提前唤醒中断服务函数：名字必须与启动文件里的向量名一致 */
void WWDG_IRQHandler(void)
{
  if (WWDG_GetFlagStatus() != RESET)
  {
    WWDG_ClearFlag();
    WWDG_Feed();
  }
}

/* 小结：至此 WWDG 已在窗口内喂狗的前提下运行，喂早或喂晚都会复位，饿死也会复位。 */

#include "stm32f10x.h"
#include "stm32f10x_gpio.h"
#include "stm32f10x_exti.h"
#include "misc.h"
#include "stm32f10x_rcc.h"

static volatile uint8_t g_keyPressed = 0;

void EXTI0_Key_Init(void)
{
  GPIO_InitTypeDef GPIO_InitStructure;
  EXTI_InitTypeDef EXTI_InitStructure;
  NVIC_InitTypeDef NVIC_InitStructure;

  /* ① 用 EXTI 必须开 AFIO 时钟，否则引脚到 EXTI 线的映射写不进去 */
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);

  /* ② 按键接 PA0，按下接地，所以配上拉输入 */
  GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_0;
  GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_IPU;
  GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
  GPIO_Init(GPIOA, &GPIO_InitStructure);

  /* ③ 把 PA0 映射到 EXTI 线 0。同一时刻一条 EXTI 线只能映射一个端口，
        PA0 与 PB0 不能同时用 */
  GPIO_EXTILineConfig(GPIO_PortSourceGPIOA, GPIO_PinSource0);

  /* ④ 下降沿触发（按下瞬间），中断模式 */
  EXTI_InitStructure.EXTI_Line    = EXTI_Line0;
  EXTI_InitStructure.EXTI_Mode    = EXTI_Mode_Interrupt;
  EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Falling;
  EXTI_InitStructure.EXTI_LineCmd = ENABLE;
  EXTI_Init(&EXTI_InitStructure);

  /* ⑤ 使能 NVIC 里的 EXTI0 通道，优先级分组要先在启动时定好 */
  NVIC_InitStructure.NVIC_IRQChannel                   = EXTI0_IRQn;
  NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 2;
  NVIC_InitStructure.NVIC_IRQChannelSubPriority        = 0;
  NVIC_InitStructure.NVIC_IRQChannelCmd                = ENABLE;
  NVIC_Init(&NVIC_InitStructure);
}

/* ⑥ 中断服务函数名必须与启动文件里的向量名完全一致 */
void EXTI0_IRQHandler(void)
{
  if (EXTI_GetITStatus(EXTI_Line0) != RESET)
  {
    g_keyPressed = 1;

    /* 必须清挂起位，否则退出中断后会立刻再次进入，程序看起来像卡死 */
    EXTI_ClearITPendingBit(EXTI_Line0);
  }
}

/* 小结：至此 PA0 的下降沿会进入 EXTI0_IRQHandler，中断里置位 g_keyPressed 并清挂起位。 */

#include "stm32f10x.h"
#include "stm32f10x_crc.h"
#include "stm32f10x_rcc.h"

/* CRC 单元挂在 AHB 总线上。算法是 CRC-32 的一个变体：
   多项式 0x04C11DB7、初值 0xFFFFFFFF、输入输出均不反转、结果不异或。
   与常见的软件 CRC-32（zlib 那种带反转的）结果不同，对端必须用同一套参数。 */
uint32_t CRC32_Caclulate(uint32_t *data, uint32_t wordCount)
{
  RCC_AHBPeriphClockCmd(RCC_AHBPeriph_CRC, ENABLE);

  /* ① 每次重新计算前必须复位数据寄存器，否则会接着上次的余数继续累加 */
  CRC_ResetDR();

  /* ② 一次性算整块（内部就是逐字写 DR） */
  return CRC_CalcBlockCRC(data, wordCount);
}

/* 流式累加的写法：适合数据分段到达（例如串口一包一包收）的场景 */
uint32_t CRC32_Stream(const uint8_t *buf, uint32_t len, uint8_t isFirstBlock)
{
  uint32_t i;
  uint32_t word;

  if (isFirstBlock)
  {
    CRC_ResetDR();
  }

  /* 注意：DR 是 32 位寄存器，必须按 32 位对齐的整字写入，
     长度也要是 4 的倍数，尾部不足 4 字节需要自己补齐 */
  for (i = 0; i + 3 < len; i += 4)
  {
    word = ((uint32_t)buf[i]) |
           ((uint32_t)buf[i + 1] << 8) |
           ((uint32_t)buf[i + 2] << 16) |
           ((uint32_t)buf[i + 3] << 24);
    (void)CRC_CalcCRC(word);
  }

  return CRC_GetCRC();
}

/* 也可用 ID 寄存器存一个 8 位标识（例如固件版本号），随 CRC 一起上报 */
void CRC_StoreID(uint8_t id)
{
  CRC_SetIDRegister(id);
}

/* 小结：至此可用硬件 CRC 单元对整块或分段数据算 CRC-32，并可把版本标识写进 ID 寄存器。 */

#include "stm32f10x.h"
#include "stm32f10x_iwdg.h"

/* IWDG 由内部 LSI（约 40kHz）驱动，与主时钟无关，主程序跑飞或时钟坏掉也能复位。
   超时 = (4 × 2^预分频系数 × 重装值) / LSI。
   预分频 64、重装 625 → 4 × 16 × 625 / 40000 ≈ 1.0 秒。
   这里取 IWDG_Prescaler_64 与 625，即约 1 秒超时。 */
void IWDG_Init(void)
{
  /* ① IWDG 由内部 LSI 直接驱动，没有对应的 RCC 使能位
        （stm32f10x_rcc.h 里只有 RCC_APB1Periph_WWDG，没有 IWDG），
        因此这一步不需要在 RCC 里开时钟。 */

  /* ② 解除写保护，否则后面的设置全部无效 */
  IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);

  /* ③ 预分频与重装值 */
  IWDG_SetPrescaler(IWDG_Prescaler_64);
  IWDG_SetReload(625);

  /* ④ 先喂一次，把计数器装进去 */
  IWDG_ReloadCounter();

  /* ⑤ 启动。注意：一旦启动就无法用软件关闭，只能靠复位 */
  IWDG_Enable();
}

/* 主循环里周期性调用；两次喂狗间隔必须小于超时时间 */
void IWDG_Feed(void)
{
  IWDG_ReloadCounter();
}

/* 可选：写保护与重装值更新完成前，对应标志会置位，可用来确认设置已生效
   while (IWDG_GetFlagStatus(IWDG_FLAG_PVU) != RESET) { }   // 预分频更新中
   while (IWDG_GetFlagStatus(IWDG_FLAG_RVU) != RESET) { }   // 重装值更新中 */

/* 小结：至此 IWDG 已启动（约 1 秒超时），主循环必须在超时前调用 IWDG_Feed。 */

#include "stm32f10x.h"
#include "misc.h"

/* 优先级分组决定「抢占优先级」和「子优先级」各占几位。
   分组 2 = 2 位抢占 + 2 位子优先级，即抢占 0~3、子优先级 0~3。 */
void NVIC_Setup(void)
{
  NVIC_InitTypeDef NVIC_InitStructure;

  /* ① 分组只能在程序开头设一次，且必须在任何 NVIC_Init 之前。
        中途改分组会让已有中断的优先级全部失效。 */
  NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);

  /* ② 串口 1 中断：抢占 1、子优先级 0 */
  NVIC_InitStructure.NVIC_IRQChannel                   = USART1_IRQn;
  NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
  NVIC_InitStructure.NVIC_IRQChannelSubPriority        = 0;
  NVIC_InitStructure.NVIC_IRQChannelCmd                = ENABLE;
  NVIC_Init(&NVIC_InitStructure);

  /* ③ 定时器 3 中断：抢占 2，低于串口，不会打断串口处理 */
  NVIC_InitStructure.NVIC_IRQChannel                   = TIM3_IRQn;
  NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 2;
  NVIC_InitStructure.NVIC_IRQChannelSubPriority        = 1;
  NVIC_Init(&NVIC_InitStructure);
}

/* SysTick 时钟源：HCLK（72MHz）或 HCLK/8（9MHz），配延时精度时要用对 */
void SysTick_Setup(void)
{
  SysTick_CLKSourceConfig(SysTick_CLKSource_HCLK);
  SysTick_Config(SystemCoreClock / 1000);   /* 1ms 一次中断 */
}

/* 做 Bootloader 跳转前，把向量表重定向到 App 区（示例 App 起始 0x08004000） */
void NVIC_RelocateVectorTable(void)
{
  NVIC_SetVectorTable(NVIC_VectTab_FLASH, 0x4000);
}

/* 小结：至此优先级分组、中断使能、SysTick 时钟源与向量表重定向都已配好。 */

