/* 小结：至此调试断点处看门狗与定时器会一起冻结，且能读到芯片的 DEVID / REVID。 */

#include "stm32f10x.h"
#include "stm32f10x_flash.h"

/* 演示在内部 Flash 末尾存一个参数。
   注意：STM32F103C8 是中容量，1KB 一页、共 64 页，
   0x0800FC00 是最后一页（第 63 页），擦掉它不会影响程序区。
   大容量型号（如 F103VE）是 2KB 一页，地址与页号都要重算。 */
#define PARAM_PAGE_ADDR   0x0800FC00UL
#define PARAM_MAGIC       0x5A5A1234UL

FLASH_Status FLASH_SaveParam(uint32_t value)
{
  FLASH_Status status;

  /* ① 解锁写保护 */
  FLASH_Unlock();

  /* ② 清掉上一次可能残留的标志 */
  FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);

  /* ③ 写之前必须先擦：Flash 只能把 1 变 0，不擦就写会得到一堆按位与的结果 */
  status = FLASH_ErasePage(PARAM_PAGE_ADDR);
  if (status != FLASH_COMPLETE)
  {
    FLASH_Lock();
    return status;
  }

  /* ④ 写一个 32 位字。F1 上通常是半字编程，FLASH_ProgramWord 内部会拆成两次半字 */
  status = FLASH_ProgramWord(PARAM_PAGE_ADDR, PARAM_MAGIC);
  if (status != FLASH_COMPLETE)
  {
    FLASH_Lock();
    return status;
  }

  status = FLASH_ProgramWord(PARAM_PAGE_ADDR + 4, value);
  if (status != FLASH_COMPLETE)
  {
    FLASH_Lock();
    return status;
  }

  /* ⑤ 校验回读，确认真的写进去了 */
  if (*(volatile uint32_t *)PARAM_PAGE_ADDR != PARAM_MAGIC)
  {
    FLASH_Lock();
    return FLASH_ERROR_PG;
  }

  /* ⑥ 重新上锁，防止程序跑飞误擦 */
  FLASH_Lock();
  return FLASH_COMPLETE;
}

/* 读取：直接按地址读内存即可，不需要解锁 */
uint32_t FLASH_LoadParam(void)
{
  if (*(volatile uint32_t *)PARAM_PAGE_ADDR != PARAM_MAGIC)
  {
    return 0xFFFFFFFFUL;   /* 未初始化过 */
  }
  return *(volatile uint32_t *)(PARAM_PAGE_ADDR + 4);
}

/* 小结：至此完成一次完整的 Flash 参数保存：解锁 → 清标志 → 擦页 → 写字 → 校验 → 上锁。 */
